function load_data(): array {
    if (!is_dir(DATA_DIR)) mkdir(DATA_DIR, 0775, true);
    $pdo=database();
    $invoiceColumnsAdded=false;foreach(['parts_cost'=>'DECIMAL(10,2) NOT NULL DEFAULT 0','labor_cost'=>'DECIMAL(10,2) NOT NULL DEFAULT 0','discount'=>'DECIMAL(10,2) NOT NULL DEFAULT 0'] as $column=>$definition){$columnInfo=$pdo->query("SHOW COLUMNS FROM services LIKE '$column'")->fetch();if(!$columnInfo){$pdo->exec("ALTER TABLE services ADD COLUMN `$column` $definition");$invoiceColumnsAdded=true;}}if($invoiceColumnsAdded)$pdo->exec('UPDATE services SET parts_cost=expense,labor_cost=GREATEST(0,income-expense) WHERE parts_cost=0 AND labor_cost=0 AND income>0');
    $emailColumn=$pdo->query("SHOW COLUMNS FROM customers LIKE 'email'")->fetch();
    if($emailColumn && $emailColumn['Null']==='NO')$pdo->exec('ALTER TABLE customers MODIFY email VARCHAR(190) NULL');
    $admin=$pdo->query("SELECT password_hash FROM users WHERE role='admin' AND email='admin@autocare.local' LIMIT 1")->fetch();
    if(!$admin){$statement=$pdo->prepare("INSERT INTO users(customer_id,email,password_hash,role) VALUES(NULL,'admin@autocare.local',?,'admin')");$statement->execute([password_hash('servis2026',PASSWORD_DEFAULT)]);$admin=$pdo->query("SELECT password_hash FROM users WHERE role='admin' AND email='admin@autocare.local' LIMIT 1")->fetch();}

    $customers=$pdo->query("SELECT c.*,u.password_hash FROM customers c LEFT JOIN users u ON u.customer_id=c.id AND u.role='client' ORDER BY c.id")->fetchAll();
    $vehicles=$pdo->query('SELECT * FROM vehicles ORDER BY id')->fetchAll();
    $serviceRows=$pdo->query('SELECT * FROM services ORDER BY id')->fetchAll();
    $requestRows=$pdo->query('SELECT * FROM service_requests ORDER BY id')->fetchAll();
    $reminderRows=$pdo->query('SELECT * FROM maintenance_reminders ORDER BY id')->fetchAll();
    $predictionRows=$pdo->query('SELECT * FROM predictions ORDER BY id')->fetchAll();

    $empty=!$customers&&!$vehicles&&!$serviceRows&&!$requestRows&&!$reminderRows&&!$predictionRows;
    if($empty){
        $backup=is_file(DATA_FILE)?json_decode((string)file_get_contents(DATA_FILE),true):null;
        $source=is_array($backup)?array_merge(seed_data(),$backup):seed_data();
        foreach($source['services'] as &$service)$service+=['status'=>'completed','expense'=>0,'problem'=>$service['type']??'Kontroll'];unset($service);
        $source['appointments']??=[];$source['predictions']??=[];$source['admin_password_hash']=$admin['password_hash'];
        save_data($source);
        return load_data();
    }

    $services=[];
    foreach($serviceRows as $row)$services[]=['id'=>(int)$row['id'],'vehicle_id'=>(int)$row['vehicle_id'],'request_id'=>$row['request_id']?(int)$row['request_id']:null,'date'=>$row['service_date'],'type'=>$row['service_type'],'problem'=>$row['problem']??'','description'=>$row['work_description']??'','cost'=>(float)$row['income'],'expense'=>(float)$row['expense'],'parts_cost'=>(float)$row['parts_cost'],'labor_cost'=>(float)$row['labor_cost'],'discount'=>(float)$row['discount'],'mileage'=>(int)$row['mileage'],'mechanic'=>$row['mechanic']??'','status'=>$row['status'],'created_at'=>$row['created_at']];
    $lastService=[];
    foreach($services as $service){$vid=(int)$service['vehicle_id'];if(!isset($lastService[$vid])||$service['date']>$lastService[$vid]['date'])$lastService[$vid]=$service;}
    foreach($vehicles as &$vehicle){$vehicle['id']=(int)$vehicle['id'];$vehicle['customer_id']=(int)$vehicle['customer_id'];$vehicle['year']=(int)$vehicle['year'];$vehicle['mileage']=(int)$vehicle['mileage'];$vehicle['last_service']=$lastService[$vehicle['id']]['date']??'';}unset($vehicle);
    $appointments=[];
    foreach($requestRows as $row)$appointments[]=['id'=>(int)$row['id'],'customer_id'=>(int)$row['customer_id'],'vehicle_id'=>(int)$row['vehicle_id'],'problem'=>$row['problem'],'requested_date'=>$row['requested_date'],'status'=>$row['status'],'created_at'=>$row['created_at']];
    $reminders=[];
    foreach($reminderRows as $row)$reminders[]=['id'=>(int)$row['id'],'vehicle_id'=>(int)$row['vehicle_id'],'title'=>$row['title'],'due_date'=>$row['due_date']??'','due_mileage'=>(int)($row['due_mileage']??0),'done'=>filter_var($row['is_done'],FILTER_VALIDATE_BOOLEAN)];
    $predictions=[];
    foreach($predictionRows as $row){$evidence=json_decode((string)($row['evidence']??'[]'),true);$predictions[]=['id'=>(int)$row['id'],'vehicle_id'=>(int)$row['vehicle_id'],'system'=>$row['predicted_system'],'risk'=>(int)$row['risk_percent'],'level'=>$row['risk_level'],'signals'=>is_array($evidence)?$evidence:[],'advice'=>$row['recommendation']??'','created_at'=>$row['created_at']];}
    $ids=[];foreach([$customers,$vehicles,$services,$appointments,$reminders,$predictions] as $rows)foreach($rows as $row)$ids[]=(int)$row['id'];
    return ['customers'=>$customers,'vehicles'=>$vehicles,'services'=>$services,'appointments'=>$appointments,'reminders'=>$reminders,'predictions'=>$predictions,'admin_password_hash'=>$admin['password_hash'],'next_id'=>($ids?max($ids):0)+1];
}
function save_data(array $data): void {
    if(!is_dir(DATA_DIR))mkdir(DATA_DIR,0775,true);
    $pdo=database();$before=$GLOBALS['DB_ORIGINAL_DATA']??[];
    $currentIds=[];foreach(['customers','vehicles','services','appointments','reminders','predictions'] as $key)$currentIds[$key]=array_map(fn($row)=>(int)$row['id'],$data[$key]??[]);
    $deleteMap=[['predictions','predictions'],['maintenance_reminders','reminders'],['services','services'],['service_requests','appointments'],['vehicles','vehicles'],['customers','customers']];
    $pdo->beginTransaction();
    try{
        foreach($deleteMap as [$table,$key])foreach($before[$key]??[] as $old){$id=(int)$old['id'];if(!in_array($id,$currentIds[$key],true)){if($key==='customers'){$q=$pdo->prepare("DELETE FROM users WHERE role='client' AND customer_id=?");$q->execute([$id]);}$q=$pdo->prepare("DELETE FROM `$table` WHERE id=?");$q->execute([$id]);}}
        $q=$pdo->prepare('INSERT INTO customers(id,name,email,phone,address) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),email=VALUES(email),phone=VALUES(phone),address=VALUES(address)');
        foreach($data['customers']??[] as $c)$q->execute([(int)$c['id'],$c['name'],!empty($c['email'])?$c['email']:null,$c['phone']??null,$c['address']??null]);
        $keepClientIds=[];foreach($data['customers']??[] as $c)if(!empty($c['password_hash']))$keepClientIds[]=(int)$c['id'];
        if($keepClientIds){$marks=implode(',',array_fill(0,count($keepClientIds),'?'));$q=$pdo->prepare("DELETE FROM users WHERE role='client' AND customer_id IS NOT NULL AND customer_id NOT IN ($marks)");$q->execute($keepClientIds);}else{$pdo->exec("DELETE FROM users WHERE role='client'");}
        $adminHash=$data['admin_password_hash']??password_hash('servis2026',PASSWORD_DEFAULT);
        $q=$pdo->prepare("INSERT INTO users(customer_id,email,password_hash,role) VALUES(NULL,'admin@autocare.local',?,'admin') ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash),role='admin'");$q->execute([$adminHash]);
        $q=$pdo->prepare("INSERT INTO users(customer_id,email,password_hash,role) VALUES(?,?,?,'client') ON DUPLICATE KEY UPDATE email=VALUES(email),password_hash=VALUES(password_hash),role='client'");
        foreach($data['customers']??[] as $c)if(!empty($c['password_hash'])&&!empty($c['email']))$q->execute([(int)$c['id'],$c['email'],$c['password_hash']]);
        $q=$pdo->prepare('INSERT INTO vehicles(id,customer_id,make,model,year,plate,vin,mileage,fuel) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE customer_id=VALUES(customer_id),make=VALUES(make),model=VALUES(model),year=VALUES(year),plate=VALUES(plate),vin=VALUES(vin),mileage=VALUES(mileage),fuel=VALUES(fuel)');
        foreach($data['vehicles']??[] as $v)$q->execute([(int)$v['id'],(int)$v['customer_id'],$v['make'],$v['model'],(int)$v['year'],$v['plate'],$v['vin']??null,(int)$v['mileage'],$v['fuel']??null]);
        $q=$pdo->prepare('INSERT INTO service_requests(id,customer_id,vehicle_id,problem,requested_date,status,created_at) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE customer_id=VALUES(customer_id),vehicle_id=VALUES(vehicle_id),problem=VALUES(problem),requested_date=VALUES(requested_date),status=VALUES(status)');
        foreach($data['appointments']??[] as $a)$q->execute([(int)$a['id'],(int)$a['customer_id'],(int)$a['vehicle_id'],$a['problem'],$a['requested_date'],in_array($a['status']??'pending',['pending','accepted','declined'],true)?$a['status']:'pending',$a['created_at']??date('Y-m-d H:i:s')]);
        $q=$pdo->prepare('INSERT INTO services(id,vehicle_id,request_id,service_date,service_type,problem,work_description,mechanic,mileage,income,expense,status,created_at,parts_cost,labor_cost,discount) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE vehicle_id=VALUES(vehicle_id),request_id=VALUES(request_id),service_date=VALUES(service_date),service_type=VALUES(service_type),problem=VALUES(problem),work_description=VALUES(work_description),mechanic=VALUES(mechanic),mileage=VALUES(mileage),income=VALUES(income),expense=VALUES(expense),status=VALUES(status),parts_cost=VALUES(parts_cost),labor_cost=VALUES(labor_cost),discount=VALUES(discount)');
        foreach($data['services']??[] as $s)$q->execute([(int)$s['id'],(int)$s['vehicle_id'],$s['request_id']??null,$s['date'],$s['type'],$s['problem']??null,$s['description']??null,$s['mechanic']??null,(int)($s['mileage']??0),(float)($s['cost']??0),(float)($s['expense']??0),in_array($s['status']??'completed',['pending','in_progress','completed'],true)?$s['status']:'completed',$s['created_at']??date('Y-m-d H:i:s'),(float)($s['parts_cost']??0),(float)($s['labor_cost']??0),(float)($s['discount']??0)]);
        $q=$pdo->prepare('INSERT INTO maintenance_reminders(id,vehicle_id,title,due_date,due_mileage,is_done) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE vehicle_id=VALUES(vehicle_id),title=VALUES(title),due_date=VALUES(due_date),due_mileage=VALUES(due_mileage),is_done=VALUES(is_done)');
        foreach($data['reminders']??[] as $r)$q->execute([(int)$r['id'],(int)$r['vehicle_id'],$r['title']?:'Mirëmbajtje',$r['due_date']?:null,(int)($r['due_mileage']??0),(int)(bool)$r['done']]);
        $q=$pdo->prepare('INSERT INTO predictions(id,vehicle_id,predicted_system,risk_percent,risk_level,evidence,recommendation,created_at) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE vehicle_id=VALUES(vehicle_id),predicted_system=VALUES(predicted_system),risk_percent=VALUES(risk_percent),risk_level=VALUES(risk_level),evidence=VALUES(evidence),recommendation=VALUES(recommendation)');
        foreach($data['predictions']??[] as $prediction){$level=in_array($prediction['level']??'I ulët',['I ulët','Mesatar','I lartë'],true)?$prediction['level']:'I ulët';$q->execute([(int)$prediction['id'],(int)$prediction['vehicle_id'],$prediction['system']??'Kontroll i përgjithshëm',min(100,max(0,(int)($prediction['risk']??0))),$level,json_encode($prediction['signals']??[],JSON_UNESCAPED_UNICODE),$prediction['advice']??null,$prediction['created_at']??date('Y-m-d H:i:s')]);}
        $pdo->commit();
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
    $GLOBALS['DB_ORIGINAL_DATA']=$data;
    // MySQL is the primary store; JSON backup is optional and may not be writable by Apache.
    if (is_writable(DATA_DIR)) {
        file_put_contents(DATA_FILE,json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),LOCK_EX);
    }
}
function csrf(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(24)); return $_SESSION['csrf']; }
function verify_post(): void { if (!hash_equals((string)($_SESSION['csrf']??''), (string)($_POST['csrf']??''))) { http_response_code(403); exit('Kërkesa nuk u verifikua. Rifresko faqen dhe provo përsëri.'); } }
function next_id(array &$d): int { $id=(int)($d['next_id']??1); $d['next_id']=$id+1; return $id; }
function vehicle_by_id(array $d, int $id): ?array { foreach($d['vehicles'] as $v) if((int)$v['id']===$id) return $v; return null; }
function customer_name(array $d, int $id): string { foreach($d['customers'] as $c) if((int)$c['id']===$id) return $c['name']; return 'Klient i fshirë'; }
function appointment_status(array $d,array $appointment): string { if(($appointment['status']??'pending')==='declined')return 'declined';foreach($d['services'] as $service)if((int)($service['request_id']??0)===(int)$appointment['id']){if(($service['status']??'')==='completed')return 'completed';if(($service['status']??'')==='in_progress')return 'in_progress';}return (string)($appointment['status']??'pending'); }
function current_role(): string { return (string)($_SESSION['user']['role']??''); }
function customer_for_user(array $d): ?array { $id=(int)($_SESSION['user']['customer_id']??0);foreach($d['customers'] as $customer)if((int)$customer['id']===$id)return $customer;return null; }
function vehicle_label(array $d, int $id): string { $v=vehicle_by_id($d,$id); return $v ? $v['make'].' '.$v['model'].' · '.$v['plate'] : 'Automjet i fshirë'; }
function vehicle_brand_key(string $make): ?string { $make=strtolower(trim($make));$brands=['lamborghini'=>'lamborghini','lamborgini'=>'lamborghini','bentley'=>'bentley','porsche'=>'porsche','audi'=>'audi','bmw'=>'bmw','mercedes'=>'mercedes','volkswagen'=>'volkswagen','vw'=>'vw','toyota'=>'toyota','range rover'=>'range_rover','range-rover'=>'range_rover','land rover'=>'land_rover','land-rover'=>'land_rover'];foreach($brands as $prefix=>$key)if(str_starts_with($make,$prefix))return $key;return null; }
function vehicle_logo_html(?array $vehicle,string $class='car-illustration'): string { $key=vehicle_brand_key((string)($vehicle['make']??''));$logos=['lamborghini'=>'brand-lamborghini.png','bentley'=>'brand-bentley.png','porsche'=>'brand-porsche.png','audi'=>'brand-audi.png','bmw'=>'brand-bmw.png','mercedes'=>'brand-mercedes.png','volkswagen'=>'brand-volkswagen.png','vw'=>'brand-volkswagen.png','toyota'=>'brand-toyota.png','range_rover'=>'brand-range-rover.png','land_rover'=>'brand-range-rover.png'];$className=h($class).' car-brand-logo';if($key&&isset($logos[$key]))return '<img class="'.$className.'" src="icon/'.h($logos[$key]).'" alt="'.h($vehicle['make']).'" loading="lazy">';return '<span class="'.$className.'" aria-hidden="true">🚘</span>'; }
