    $xref=strlen($pdf);$pdf.="xref\n0 ".count($offsets)."\n0000000000 65535 f \n";for($i=1;$i<count($offsets);$i++)$pdf.=sprintf('%010d 00000 n ',$offsets[$i])."\n";$pdf.="trailer\n<< /Size ".count($offsets)." /Root 1 0 R >>\nstartxref\n$xref\n%%EOF";header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="fatura-servisi-'.$invoice['id'].'.pdf"');header('Content-Length: '.strlen($pdf));echo $pdf;exit;
}
function flash(string $message, string $kind='success'): void { $_SESSION['flash']=['message'=>$message,'kind'=>$kind]; }
function prediction(array $v, array $d): array {
    $vehicleServices=array_values(array_filter($d['services'],fn($s)=>(int)$s['vehicle_id']===(int)$v['id']));
    usort($vehicleServices,fn($a,$b)=>strcmp($b['date'],$a['date']));
    $last=$vehicleServices[0]??null;
    $kmSince=$last ? max(0,(int)$v['mileage']-(int)$last['mileage']) : (int)$v['mileage'];
    $age=max(0,(int)date('Y')-(int)$v['year']);
    $risk=12; $signals=[]; $system='Kontroll i përgjithshëm'; $advice='Vazhdo me mirëmbajtjen periodike dhe regjistro çdo simptomë të re.';
    if($kmSince>=15000){$risk+=25;$signals[]='Kanë kaluar mbi 15,000 km nga servisi i fundit.';$system='Motori / vajosja';$advice='Kontrollo nivelin dhe gjendjen e vajit; planifiko servis të rregullt.';}
    elseif($kmSince>=10000){$risk+=15;$signals[]='Kilometrazhi nga servisi i fundit po i afrohet intervalit të rekomanduar.';$system='Motori / filtrat';$advice='Planifiko kontrollin e vajit dhe filtrave së shpejti.';}
    if($age>=8){$risk+=15;$signals[]='Automjeti është 8 ose më shumë vjet i vjetër.';if($system==='Kontroll i përgjithshëm')$system='Bateria / sistemi elektrik';}
    if((int)$v['mileage']>=120000){$risk+=12;$signals[]='Kilometrazhi total është mbi 120,000 km.';if($system==='Kontroll i përgjithshëm')$system='Frenat / amortizimi';}
    $openReminders=array_filter($d['reminders'],fn($r)=>(int)$r['vehicle_id']===(int)$v['id']&&!$r['done']&&($r['due_date']<=date('Y-m-d')||(int)$r['due_mileage']<=(int)$v['mileage']));
    if(count($openReminders)){ $risk+=18;$signals[]='Ka kujtesë mirëmbajtjeje të vonuar.';$system='Mirëmbajtja e planifikuar';$advice='Përfundo kujtesën e vonuar dhe regjistro rezultatin e kontrollit.'; }
    $risk=min(92,$risk); $level=$risk>=55?'I lartë':($risk>=30?'Mesatar':'I ulët');
    if(!$signals)$signals[]='Nuk u gjet sinjal i fortë nga të dhënat e regjistruara.';
    return ['risk'=>$risk,'level'=>$level,'system'=>$system,'advice'=>$advice,'signals'=>$signals,'km_since'=>$kmSince,'created_at'=>date('Y-m-d H:i')];
}
function assistant_assess(string $input): array {
    $text=strtr(mb_strtolower($input,'UTF-8'),['ë'=>'e','ç'=>'c','Ë'=>'e','Ç'=>'c']);
    $has=function(array $words)use($text):bool{foreach($words as $word)if(str_contains($text,$word))return true;return false;};
    $result=['title'=>'Kontroll i përgjithshëm','urgency'=>'Kontroll i planifikuar','tone'=>'normal','summary'=>'Përshkrimi nuk ka mjaft detaje për të ngushtuar shkakun.','causes'=>['Një pjesë e liruar ose e konsumuar','Një problem i vogël elektrik ose mekanik'],'steps'=>['Vëre nëse zhurma përsëritet dhe kur ndodh.','Kontrollo nëse janë ndezur drita paralajmëruese në panel.'],'followup'=>'A ndodh zhurma vetëm kur ndizet makina, gjatë vozitjes, apo edhe kur frenon?'];
    if($has(['fren','pedale','nuk ndal','fishkell','fishkellim','gervish'])){
        $result=['title'=>'Frenat mund të kërkojnë kontroll','urgency'=>'Kontroll sa më shpejt','tone'=>'warning','summary'=>'Zhurma gjatë frenimit mund të vijë nga pllakat e konsumuara, papastërtia ose disqet e frenave. Përshkrimi nuk mjafton për ta konfirmuar shkakun.','causes'=>['Pllaka frenash të konsumuara','Papastërti ose gur i vogël te disku','Disk frenash i konsumuar ose i deformuar'],'steps'=>['Nëse frenimi është dobësuar, pedali fundoset ose makina tërhiqet anash, ndalo në vend të sigurt dhe mos vazhdo vozitjen.','Nëse dëgjohet gërryerje metalike, cakto kontroll urgjent te mekaniku.'],'followup'=>'A dëgjohet zhurma vetëm kur shtyp frenën? A është pedali ose frenimi ndryshe nga zakonisht?'];
    } elseif($has(['tym','tymi','djeg','ere benzine','ere nafte','karburant','mbinxeh','temperatura','vajin','drita e vajit','oil pressure'])){
        $result=['title'=>'Sinjal që kërkon kujdes të menjëhershëm','urgency'=>'Ndalo në vend të sigurt','tone'=>'danger','summary'=>'Simptoma që përshkruan mund të lidhet me mbinxehje, rrjedhje ose presion të vajit/karburantit.','causes'=>['Rrjedhje ose lëng që prek pjesë të nxehta','Problem me ftohjen ose vajosjen','Rrjedhje karburanti ose problem elektrik'],'steps'=>['Ndalo në vend të sigurt dhe fik motorin nëse ka tym, erë të fortë karburanti, temperaturë të kuqe ose dritë të kuqe të vajit.','Mos e hap kapakun e radiatorit kur motori është i nxehtë.','Kontakto mekanikun ose asistencën rrugore para se të vazhdosh.'],'followup'=>'A ke parë tym, rrjedhje, temperaturë të lartë ose ndonjë dritë të kuqe në panel?'];
    } elseif($has(['timoni','drejtim','dridhet','dridhje','vibr'])){
        $result=['title'=>'Dridhje ose problem në drejtim','urgency'=>'Kontroll sa më shpejt','tone'=>'warning','summary'=>'Dridhjet mund të lidhen me gomat, balancimin, frenat ose pjesët e drejtimit.','causes'=>['Balancim ose presion jo i duhur i gomave','Gomë e dëmtuar ose rrotë e liruar','Pjesë të drejtimit ose të suspensionit të konsumuara'],'steps'=>['Kontrollo vizualisht nëse ndonjë gomë është e dëmtuar ose dukshëm e shfryrë.','Nëse timoni bëhet i vështirë ose makina nuk mbahet drejt, ndalo dhe kërko kontroll.'],'followup'=>'Dridhja ndihet në timon, në gjithë makinën, apo vetëm kur frenon?'];
    } elseif($has(['zhurm','zhurum','tingull','trokit','klik','fishk','gervish','rrah'])){
        $startup=$has(['ndiz','ndez','start','niset','nis makin','mengjes']);
        if($startup){
            if($has(['klik','click'])){$causes=['Bateri e dobët ose kontakt i liruar te klemat','Motori i ndezësit (starteri) mund të mos angazhohet mirë','Lidhje elektrike ose alternator që nuk e mbush baterinë'];$summary='Klikimi gjatë ndezjes shpesh lidhet me baterinë ose starterin, por shkaku duhet kontrolluar.';}
            elseif($has(['fishk','cinger','rrip','shush'])){$causes=['Rrip ndihmës i liruar ose i konsumuar','Tensionues ose rrotull e rripit e konsumuar','Rrjedhje ajri ose pjesë plastike e liruar'];$summary='Një fishkëllimë e shkurtër gjatë ndezjes mund të vijë nga rripi ose tensionuesi.';}
            elseif($has(['gervish','metal','grind','cak'])){$causes=['Starteri nuk shkëputet si duhet pas ndezjes','Dhëmbë të konsumuar te starteri ose volantja','Pjesë metalike e liruar'];$summary='Gërryerja metalike gjatë ndezjes mund të lidhet me starterin. Shmang ndezjet e përsëritura derisa të kontrollohet.';}
            else{$causes=['Bateri e dobët ose starter që po konsumohet','Rrip ndihmës/tensionues që bën zhurmë në ndezje','Pjesë e liruar ose dridhje e motorit gjatë startimit'];$summary='Zhurma e lehtë vetëm gjatë ndezjes mund të vijë nga bateria/starteri, rripi ose një pjesë e liruar. Lloji dhe kohëzgjatja e zhurmës ndihmojnë në dallimin e tyre.';}
            $result=['title'=>'Zhurmë gjatë ndezjes','urgency'=>'Kontroll i planifikuar','tone'=>'normal','summary'=>$summary,'causes'=>$causes,'steps'=>['Vëre nëse zhurma zgjat vetëm 1–2 sekonda apo vazhdon pasi motori ndizet.','Shëno nëse është klikim, fishkëllimë apo gërryerje metalike.','Nëse ndezja vështirësohet ose zhurma përkeqësohet, cakto kontroll te mekaniku.'],'followup'=>'Si tingëllon më shumë: klikim, fishkëllimë, trokitje apo gërryerje? Sa sekonda zgjat?'];
        } else {$result['title']='Zhurmë mekanike — nevojitet më shumë informacion';$result['summary']='Zhurma mund të vijë nga disa sisteme dhe vendi/kushti kur shfaqet është i rëndësishëm.';$result['causes']=['Pjesë e liruar ose mbrojtëse që vibron','Rrip, kushinetë ose pjesë e motorit e konsumuar','Gomë, frenë ose suspension — në varësi të momentit kur dëgjohet'];$result['steps']=['Mos e prek pjesën e motorit derisa të ftohet.','Shëno shpejtësinë dhe kushtin kur shfaqet zhurma.','Nëse shoqërohet me dritë të kuqe, tym ose humbje të fuqisë, ndalo në vend të sigurt.'];$result['followup']='Kur dëgjohet: në ndezje, gjatë përshpejtimit, në kthesa apo kur frenon?';}
    }
    return $result;
}

